  name text PRIMARY KEY
);
CREATE TABLE IF NOT EXISTS tokens (
  username  text        NOT NULL,
  key       text        NOT NULL,
  token     text        NOT NULL,
  cidr      text[]      NOT NULL DEFAULT '{}',
  readonly  boolean     NOT NULL DEFAULT false,
